from src.nodes.base import BaseNode
from src.runtime.semantic import get_scene_intent_extractor, get_intent_serializer
import json

class Hou_Mcp_Scene_Intent_Extract(BaseNode):
    name = "hou_mcp_scene_intent_extract"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("prompt",       "string", widget_type="text")
        self.add_input("context_json", "string", widget_type="text", default="{}")
        self.add_output("scene_intent_json", "string")
        self.add_output("intent_id",         "string")
        self.add_output("environment",       "string")
        self.add_output("confidence",        "float")
        self.add_output("extraction_method", "string")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        prompt = inputs.get("prompt", "") or ""
        if not prompt.strip():
            self.log_error("No prompt provided.")
            return {"scene_intent_json": "", "intent_id": "", "environment": "",
                    "confidence": 0.0, "extraction_method": "", "exec_out": True}
        try:
            ctx_raw = inputs.get("context_json", "{}") or "{}"
            context = json.loads(ctx_raw) if ctx_raw.strip() not in ("", "{}") else {}
        except Exception:
            context = {}
        try:
            extractor = get_scene_intent_extractor()
            result = await extractor.extract(prompt, context=context)
            if not result.ok or result.intent is None:
                self.log_error(f"Extraction failed: {result.errors}")
                return {"scene_intent_json": "", "intent_id": "", "environment": "",
                        "confidence": 0.0, "extraction_method": "", "exec_out": True}
            intent = result.intent
            intent_json = get_intent_serializer().to_json(intent)
            method = "llm" if intent.llm_enhanced else "keyword"
            self.log_info(f"Extracted intent: env={intent.environment}, confidence={intent.confidence:.2f}, method={method}")
            return {
                "scene_intent_json": intent_json,
                "intent_id":        intent.intent_id,
                "environment":      intent.environment or "",
                "confidence":       float(intent.confidence),
                "extraction_method": method,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Intent extraction failed: {exc}")
            return {"scene_intent_json": "", "intent_id": "", "environment": "",
                    "confidence": 0.0, "extraction_method": "", "exec_out": True}

def register_node():
    return Hou_Mcp_Scene_Intent_Extract
